#!/usr/bin/env python3
import csv, glob, json, re
from collections import defaultdict
from pathlib import Path

DATA = Path('/app/data')
OUT = Path('/app/output/solution.json')

# Each expression captures one complete reason phrase, excluding free-form status noise.
PATTERNS = [
    ('FIXTURE_CONTACT', re.compile(r'(?:治[具俱]/探针接[触處]不良，重插后偶尔OK|fixtur(?:e)? contact unstable, reseat sometimes passes)', re.I), False),
    ('PROBE_WORN', re.compile(r'(?:探针磨损导致接触差，建议换针|probe worn causing bad contact, replace pin)', re.I), False),
    ('FLASH_FAIL', re.compile(r'(?:烧录失败/写入失败，重烧不稳定|program/fla(?:sh|hs) write failed, refla(?:sh|hs) unstable)', re.I), False),
    ('LEAKAGE', re.compile(r'(?:HiPot 漏[电點]超规，疑似绝缘不良/污染|HiPot leakage over spec, suspect insulation/contamination)', re.I), False),
    ('CURRENT_HIGH', re.compile(r'(?:静态电流偏高，疑似短路趋势/器件异常|idle current high, suspect partial short/component issue)', re.I), False),
    ('CHECKSUM_FAIL', re.compile(r'(?:校[验研]失败/CRC挂，疑似程序包或数据异常|CRC/(?:checksum|cheksum) verify failed, package/data issue)', re.I), False),
    ('BOOT_FAIL', re.compile(r'(?:开机启动失败，卡logo/进不了系统|boot failed, stuck at logo / cannot boot|OS fail，启动不了|OS fail, cannot boot)', re.I), False),
    ('VERSION_MISMATCH', re.compile(r'(?:版本不符/下错程序，需确认FW版本|version mismatch / wrong FW image)', re.I), False),
    ('HIGH_RES', re.compile(r'(?:HIGH_RES issue|HIGH_RES)', re.I), False),
    ('CAL_DATA_FAIL', re.compile(r'(?:RF校准数据写读失败，重校仍挂|RF cal data R/W failed, recal still NG)', re.I), False),
    ('CONNECTOR_WEAR', re.compile(r'(?:RF接口插拔磨损，loss大导致校准失败|RF connector wear, high loss causing cal fail)', re.I), False),
    ('CONTAMINATION', re.compile(r'(?:疑似助焊剂残留/污染影响测试|suspect residue/contamination affecting test)', re.I), False),
    ('ESD', re.compile(r'(?:疑似ESD损伤，需复测确认|ESD suspected, verify with retest)', re.I), False),
    ('PRESSURE_MARK', re.compile(r'(?:治[具俱]压伤pad/走线，导致不良|fixture pressure mark, pad/trace damage)', re.I), False),
    ('MISSING', re.compile(r'(?:少件/漏贴，目检确认|missing component, visual confirm)', re.I), False),
    ('REVERSED', re.compile(r'(?:极性反向/装反，需返修|polarity reversed, rework needed)', re.I), False),
    ('OPEN', re.compile(r'(?P<subject>[A-Za-z][A-Za-z0-9_]*)\s+(?:OS\s*\(open\)\s*seen|OS，像开[路鲁]|open, suspect cold solder/missing solder|开[路鲁]，疑似虚[焊汉]/少锡)', re.I), True),
    ('SHORT', re.compile(r'(?P<subject>[A-Za-z][A-Za-z0-9_]*)\s+(?:OS\s*\(short\)\s*seen|OS，像短[路露]|short, possible solder bridge|短[路露]，可能连锡/桥连)', re.I), True),
    ('COLD_SOLDER', re.compile(r'(?P<subject>[A-Za-z][A-Za-z0-9_]*)\s+(?:intermittent, suspect cold solder|功能不稳，疑似虚焊/浮高)', re.I), True),
    ('BST_GENERIC', re.compile(r'(?:BST 异常，需确认原因|BST abnormal, need check)', re.I), False),
]

TYPO_MARKERS = ('治俱', '接處', 'fixtur contact', 'flahs', 'refla hs', '漏點', '校研', 'cheksum', '开鲁', '短露', '虚汉')
ENTITY_CATEGORIES = {'OPEN', 'SHORT', 'COLD_SOLDER', 'MISSING', 'REVERSED'}

codebooks = defaultdict(list)
code_by_product = defaultdict(list)
for path in sorted(glob.glob(str(DATA / 'codebook_*.csv'))):
    with open(path, encoding='utf-8-sig', newline='') as f:
        for row in csv.DictReader(f):
            row['scopes'] = set(row['station_scope'].split(';'))
            codebooks[(row['product_id'], row['category_lv2'])].append(row)
            code_by_product[row['product_id']].append(row)


def tokens(text):
    return set(re.findall(r'[A-Za-z][A-Za-z0-9_]*', text.upper()))


def labels(rows):
    return {r['standard_label'] for r in rows}


def choose_code(product, category, subject, station):
    """Return row, selection mode, ambiguity reason, and whether station is in scope."""
    rows = list(codebooks.get((product, category), []))
    if not rows:
        return None, None, 'category is absent from this product codebook', False

    mode = 'direct category phrase'
    if category in ('MISSING', 'REVERSED'):
        if not subject:
            return None, None, 'the component is not identified', False
        matched = [r for r in rows if subject.upper() in tokens(r['standard_label'])]
        rows = matched
        mode = 'explicit component'
    elif category in ('OPEN', 'SHORT'):
        matched = [r for r in rows if subject and subject.upper() in tokens(r['standard_label'])]
        if not matched:
            return None, None, f'no {category.lower()} entry names {subject}', False
        rows = matched
        mode = 'exact signal/component'
    elif category == 'COLD_SOLDER':
        direct = [r for r in rows if subject and subject.upper() in tokens(r['standard_label'])]
        if direct:
            rows = direct
            mode = 'explicit component'
        else:
            # Infer a component only when the electrical entries associate the signal
            # with exactly one component that also has a cold-solder label.
            electrical = codebooks.get((product, 'OPEN'), []) + codebooks.get((product, 'SHORT'), [])
            linked_components = set()
            cold_components = {next((t for t in tokens(r['standard_label']) if re.fullmatch(r'[A-Z]+\d+', t)), '') for r in rows}
            for r in electrical:
                if subject and subject.upper() in tokens(r['standard_label']):
                    for token in tokens(r['standard_label']):
                        if token in cold_components:
                            linked_components.add(token)
            if len(linked_components) != 1:
                detail = 'no unique codebook component association' if linked_components else f'no cold-solder entry can be linked to {subject}'
                return None, None, detail, False
            component = next(iter(linked_components))
            rows = [r for r in rows if component in tokens(r['standard_label'])]
            mode = f'unique codebook association {subject}→{component}'

    if not rows:
        return None, None, 'no matching entry remains', False
    distinct = labels(rows)
    if len(distinct) != 1:
        return None, None, 'multiple distinct codebook labels remain', False

    scoped = [r for r in rows if station in r['scopes']]
    in_scope = bool(scoped)
    eligible = scoped or rows
    # Identical labels/codes are otherwise indistinguishable; choose the lowest code.
    row = min(eligible, key=lambda r: r['code'])
    alias_count = len(eligible)
    return row, (mode, alias_count), None, in_scope


def detected_segments(text):
    found = []
    for category, pattern, has_subject in PATTERNS:
        for match in pattern.finditer(text):
            subject = match.groupdict().get('subject') if has_subject else None
            key = (category, subject.upper() if subject else None)
            found.append({'category': category, 'subject': subject.upper() if subject else None,
                          'span': match.group(0), 'start': match.start(), 'key': key})
    # Repeated Chinese/English renderings of the same reason are one normalized segment.
    unique = {}
    for item in sorted(found, key=lambda x: (x['start'], x['category'])):
        unique.setdefault(item['key'], item)
    return sorted(unique.values(), key=lambda x: (x['start'], x['category']))


def is_typo(span):
    low = span.lower()
    return any(marker.lower() in low for marker in TYPO_MARKERS)


def normalize_one(record, item, index):
    category, subject, span = item['category'], item['subject'], item['span']
    if category == 'BST_GENERIC':
        return {'segment_id': f"{record['record_id']}-S{index}", 'span_text': span,
                'pred_code': 'UNKNOWN', 'pred_label': '', 'confidence': 0.18,
                'rationale': 'The text reports an unspecified BST abnormality, but it does not identify a defect reason represented unambiguously in the product codebook; engineering review is required.'}

    row, mode_info, ambiguity, in_scope = choose_code(record['product_id'], category, subject, record['station'])
    if row is None:
        confidence = 0.33 if category in ENTITY_CATEGORIES else 0.24
        if ambiguity == 'multiple distinct codebook labels remain' or (ambiguity and 'unique' in ambiguity):
            confidence = 0.39
        if is_typo(span):
            confidence = max(0.12, confidence - 0.08)
        subject_note = f' for “{subject}”' if subject else ''
        return {'segment_id': f"{record['record_id']}-S{index}", 'span_text': span,
                'pred_code': 'UNKNOWN', 'pred_label': '', 'confidence': round(confidence, 2),
                'rationale': f'The phrase indicates {category}{subject_note}, but {ambiguity} in the {record["product_id"]} codebook; routed to engineering review.'}

    mode, alias_count = mode_info
    if category in ('OPEN', 'SHORT'):
        confidence = 0.96
    elif category == 'COLD_SOLDER' and mode.startswith('unique codebook association'):
        confidence = 0.84
    elif category in ('MISSING', 'REVERSED') and mode == 'explicit component':
        confidence = 0.94
    else:
        confidence = 0.91
    if alias_count > 1:
        confidence -= 0.11
    if not in_scope:
        confidence -= 0.18
    if is_typo(span):
        confidence -= 0.10
    confidence = round(max(0.58, min(0.98, confidence)), 2)

    evidence = f'The phrase “{span}” matches {row["category_lv2"]}'
    if mode.startswith('unique codebook association'):
        evidence += f' through the {mode.replace("unique codebook association ", "codebook’s unique ")}'
    elif subject:
        evidence += f' by {mode} “{subject}”'
    scope_note = f'; station {record["station"]} is within the listed scope' if in_scope else f'; station {record["station"]} is outside the listed scope, reducing confidence'
    alias_note = '; the lowest code was selected deterministically among equivalent-label entries' if alias_count > 1 else ''
    rationale = evidence + scope_note + alias_note + '.'
    return {'segment_id': f"{record['record_id']}-S{index}", 'span_text': span,
            'pred_code': row['code'], 'pred_label': row['standard_label'],
            'confidence': confidence, 'rationale': rationale}


records = []
with open(DATA / 'test_center_logs.csv', encoding='utf-8-sig', newline='') as f:
    for record in csv.DictReader(f):
        detected = detected_segments(record['raw_reason_text'])
        if detected:
            normalized = [normalize_one(record, item, i) for i, item in enumerate(detected, 1)]
        else:
            normalized = [{
                'segment_id': f"{record['record_id']}-S1",
                'span_text': record['raw_reason_text'],
                'pred_code': 'UNKNOWN',
                'pred_label': '',
                'confidence': 0.12,
                'rationale': 'No sufficiently specific phrase could be aligned with this product codebook; routed to engineering review.'
            }]
        records.append({
            'record_id': record['record_id'],
            'product_id': record['product_id'],
            'station': record['station'],
            'engineer_id': record['engineer_id'],
            'raw_reason_text': record['raw_reason_text'],
            'normalized': normalized,
        })

OUT.parent.mkdir(parents=True, exist_ok=True)
with open(OUT, 'w', encoding='utf-8') as f:
    json.dump({'records': records}, f, ensure_ascii=False, indent=2)
    f.write('\n')
print(f'wrote {OUT} with {len(records)} records and {sum(len(r["normalized"]) for r in records)} segments')

